mapper.codeEditorJavascript:
// RULE (Steve 11/11/2026): answer to the immediate advance offer (ManyChat flow "הקדמה מיידית אחרי הקלדה"). Writes the answer to tab "הקדמה מיידית"; on "כן" alerts the selling rep (first name only) via Green API, never Fri/Sat (then the hourly run sends it Sunday). Do not remove.
// RULE (Steve 12/11/2026): "כן" on an offer for tomorrow/Sunday does NOT alert the rep - ManyChat asks the customer for time windows and "הקדמות 9" sends the request (or passes it to the rep). Column N is marked "שאלון חלונות" so the hourly run won't alert either. Only "היום" offers go straight to the rep.
// RULE (Steve 15/11/2026): offers are now "היום או מחר" (before 12:00) or "מחר" (after). Only an offer that is exactly "היום" goes straight to the rep; "היום או מחר" goes to the windows questionnaire like "מחר" (a free-text "היום" answer is passed to the rep by הקדמות 9; no window within an hour -> הקדמות 10 alerts the rep). Do not remove.
const BIDI=new RegExp('[\\s'+String.fromCharCode(8206,8207)+']+','g'); const norm=s=>String(s==null?'':s).replace(BIDI,' ').trim();
const vrs=input.ranges||[];
const rangeOf=vr=>String((vr.valueRange||vr||{}).range||'');
const valsOf=vr=>((vr.valueRange||vr||{}).values)||[];
const log=valsOf(vrs.find(v=>rangeOf(v).includes('הקדמה מיידית'))||{});
const targets=valsOf(vrs.find(v=>rangeOf(v).includes('יעדים'))||{}).filter(r=>r&&norm(r[0]));
const id=norm(input.id); const ans=norm(input.answer);
let row=-1; for(let i=log.length-1;i>=1;i--){ if(norm(log[i][10])===id){row=i;break;} }
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const dow=nowIL.getDay(), mins=nowIL.getHours()*60+nowIL.getMinutes();
const repOK=dow<=4&&mins>=8*60&&mins<21*60;
const stamp=nowIL.getDate()+'/'+(nowIL.getMonth()+1)+' '+String(nowIL.getHours()).padStart(2,'0')+':'+String(nowIL.getMinutes()).padStart(2,'0');
if(row<0||!id) return {found:false, alert:''};
const r=log[row]; const already=norm(r[13]);
const isToday=norm(r[8])==='היום';
const toIntl=p=>{let d=String(p||'').replace(/\D/g,''); if(d.startsWith('972')) return d; if(d.startsWith('0')) d=d.slice(1); return d?'972'+d:'';};
const rep=norm(r[5]); let m=targets.filter(x=>norm(x[0])===rep); if(!m.length&&rep){const f=rep.split(' ')[0]; m=targets.filter(x=>{const a=norm(x[0]); return a===f||a.split(' ')[0]===f;});}
const ph=m.length?toIntl(m[0][1]):''; const first=m.length?norm(m[0][0]).split(' ')[0]:'';
let alert='';
const sendNow=ans==='כן'&&!already&&repOK&&isToday;
if(sendNow){
 const msg=(first?'היי '+first+', ':'')+'🙋 לקוח שלך ענה שהוא רוצה להקדים את ההתקנה!\n\n👤 '+norm(r[2])+(norm(r[4])?' (לקוח '+norm(r[4])+')':'')+'\n📱 '+norm(r[3])+'\n📅 מתואם כרגע: '+(norm(r[6])?norm(r[6])+' '+norm(r[7]):'עוד אין תאריך')+'\n\nתתקשר אליו עכשיו ותסגור יום וחלון שעות.\n• להיום: דרך משווקים יס (050-2552817)\n• ליום אחר: שולחים לבוט, למשל: הקדמה '+(norm(r[4])||'<מספר לקוח>')+' 17/11 10-12'+(input.chat?'\n\n💬 השיחה עם הלקוח: '+norm(input.chat):'');
 alert=JSON.stringify({chatId:(ph||'972544604246')+'@c.us', message:(ph?'':'⚠️ לא מצאתי טלפון לנציג "'+rep+'" בלשונית יעדים:\n\n')+msg});
}
const vals=[ans,stamp]; if(sendNow) vals.push('כן'); else if(ans==='כן'&&!isToday&&!already) vals.push('שאלון חלונות');
return {found:true, alert, body:JSON.stringify({valueInputOption:'RAW',data:[{range:"'הקדמה מיידית'!L"+(row+1)+':'+(vals.length===3?'N':'M')+(row+1),values:[vals]}]})};
